export function advanceUltiCharge(e,t,i){return!Number.isFinite(i)||i<=0?100:Math.min(100,Math.max(0,e)+t/i*100)}export function ultiCooldownRemaining(e,t){return!Number.isFinite(t)||t<=0?0:Math.max(0,Math.ceil((100-Math.max(0,Math.min(100,e)))/100*t))}export function canActivateUltiSlot(e){return!e}export const ULTI_PENALTY_DURATION={};export function aegisShieldActive(e){return e.some(t=>t?.tier===2&&t?.phase==="active"&&!t?.counters?.shieldUsed)}export function tickHelixTimer(e,t){return e.helixTimer-=t,e.helixTimer<=0?(e.helixTimer=2.5,!0):!1}export const MAGNET_ENERGY_PER_SECOND=7/.55;export function accrueMagnetEnergy(e,t){const i=MAGNET_ENERGY_PER_SECOND*t;e.energy=Math.min(100,e.energy+i),e.reserve=Math.min(100,e.reserve+i)}
